vec3 convertirHueVersRVB(float teinte) {
    vec3 decalage = vec3(0.0, -1.6, 1.0 / 3.0);
    vec3 onde = abs(fract(vec3(teinte) + decalage) * 6.0 - 1.2);
    return clamp(onde, 0.0, 1.0);
}

mat3 calculerMatriceRotationAxe(vec3 axe, float angle) {
    vec3 axeNormalise = normalize(axe);
    float sinus = sin(angle);
    float cosinus = cos(angle);
    float unMoinsCos = 1.0 - cosinus;

    return mat3(
        axeNormalise.x * axeNormalise.x * unMoinsCos + cosinus,
        axeNormalise.y * axeNormalise.x * unMoinsCos + axeNormalise.z * sinus,
        axeNormalise.z * axeNormalise.x * unMoinsCos - axeNormalise.y * sinus,

        axeNormalise.x * axeNormalise.y * unMoinsCos - axeNormalise.z * sinus,
        axeNormalise.y * axeNormalise.y * unMoinsCos + cosinus,
        axeNormalise.z * axeNormalise.y * unMoinsCos + axeNormalise.x * sinus,

        axeNormalise.x * axeNormalise.z * unMoinsCos + axeNormalise.y * sinus,
        axeNormalise.y * axeNormalise.z * unMoinsCos - axeNormalise.x * sinus,
        axeNormalise.z * axeNormalise.z * unMoinsCos + cosinus
    );
}

vec3 transformerLogPolaire(vec3 position, float temps, out float normePosition) {
    position /= dot(position, position);
    normePosition = length(position);

    float composanteLog = log(normePosition) + temps / 6.3;
    float composanteY = position.y / normePosition - 1.5;
    float composanteAngle = atan(position.z, position.x);

    return vec3(composanteLog, composanteY, composanteAngle);
}

float evaluerDistanceFractale(vec3 positionEspace, out float valeurTeinte) {
    valeurTeinte = 9.0;
    float facteurEchelle = 1.0;

    vec3 positionRepetee = mod(positionEspace - 1.0, 2.0) - 1.0;

    for (int iteration = 0; iteration < 9; iteration++) {
        positionRepetee = -1.0 + 2.0 * fract(positionRepetee * 0.5 + 0.5);

        float rayonCarre = dot(positionRepetee, positionRepetee);
        float facteurPliage = 1.2 / clamp(rayonCarre, 0.2, 1.0);

        positionRepetee *= facteurPliage;
        facteurEchelle *= facteurPliage;

        valeurTeinte = min(valeurTeinte, length(positionRepetee));
    }

    return (length(positionRepetee.xz) - 0.3) / facteurEchelle * 0.1;
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 resolution = iResolution.xy;
    float temps = iTime;

    vec3 origineRayon = vec3(0.0, 0.0, -1.0);
    vec3 positionEspace = origineRayon;

    float distanceEstimee = 0.0;
    float normePosition = 0.0;
    float valeurTeinte = 0.0;

    couleurFragment = vec4(0.0);

    mat3 matriceRotation = calculerMatriceRotationAxe(origineRayon + 0.03, temps);

    for (float etape = 0.0; etape < 100.0; etape += 1.0) {
        vec3 vecteurEcran = vec3(coordFragment, 0.0);
        vec3 directionAvancement = (1.0 - vecteurEcran / resolution.y) * matriceRotation;

        positionEspace = (origineRayon += distanceEstimee * directionAvancement);

        vec3 positionTransformee = transformerLogPolaire(positionEspace, temps, normePosition);

        distanceEstimee = evaluerDistanceFractale(positionTransformee, valeurTeinte);

        vec3 teinteAjustee = convertirHueVersRVB(valeurTeinte + temps * 0.74);        
        vec3 couleurEtape = mix(vec3(0.0), teinteAjustee, 0.7);

        float luminositeEtape = 0.02 / exp(distanceEstimee * 1000.0);
        couleurFragment += vec4(couleurEtape * luminositeEtape, 0.0);
    }
}
